#!/usr/bin/env python3
"""Persist independent L14 review without changing the author batch."""
import collections,datetime,hashlib,json,sys
from pathlib import Path
R=Path(__file__).resolve().parents[1];sys.path.insert(0,str(R/'scripts'))
from validate import CHECK_KEYS,question_hash
load=lambda p:json.loads((R/p).read_text())
blindpath=R/'audits/blind-answers-W03-L14-independent.json';blind=load(blindpath)
assert blind['complete'] and blind['solvedBeforeAnswerSeen'] and not blind['keyedBatchOpened']
packet=load('audits/blind-W03-L14.json');batchpath=R/'data/question-batches/W03-L14.json';batch=load(batchpath)
qs={q['id']:q for q in batch['questions']};answers={a['questionId']:a for a in blind['answers']}
assert len(qs)==len(answers)==len(packet)==53
for p in packet:
 q=qs[p['id']]
 for key in ['stem','version','selectionMode','options','assumptions','difficulty']:assert q[key]==p[key]
 assert question_hash(q)==p['questionSha256']
 assert set(q['correctOptionIds'])==set(answers[q['id']]['independentAnswerOptionIds'])
comp=load('audits/W03-L14-independent-computations.json');assert comp['allPassed'] and comp['caseCount']==2218
flags={}
def flag(i,key,finding):flags.setdefault(f'W03-L14-Q{i:03d}',[]).append({'check':key,'finding':finding})
for i,f in {
 2:'Replace the static-only/moving-only and one-DOF/six-DOF restrictions with plausible competing computational/analytical emphasis pairings. The current alternatives can be eliminated without knowing the comparison slide. Keep the historical source-attributed preference rather than a universal runtime assertion.',
 11:'Use plausible named analytical extensions or function-role confusions rather than deleting all generalized forces, changing K−U to K+U, or merely shifting a constant datum. The current options do not meaningfully test recognition of the Rayleigh term. Preserve the explicit source terminology and bounded scope.',
 12:'Replace the no-actuator-torque, at-most-one-coordinate and always-zero-potential alternatives with plausible statements about the limitations of the displayed conservative energy formulation. The current wrong alternatives are contradicted by the defining equations themselves and do not test the specific source attribution. Do not turn the printed blanket limitation into a universal theorem.',
 36:'Write the complete U-gradient vector in options o2 and o3, or introduce a named vector with its full components in the stem. "The same stated U vector" currently has no unique stem-level antecedent and implicitly relies on another option, which is unsafe under shuffling. Keep every alternative self-contained or explicitly tied to a defined symbol.',
 53:'Replace the desired-diagonal-appearance/infer-energy and delete-all-inertia workflows with realistic derivative/order mistakes, such as holding a configuration-dependent coefficient constant during the total derivative or substituting a special state too early. Keep the correct independent-coordinate/energy/derivative/effort sequence.'
}.items():flag(i,'distractors',f)
for i,why in {
 12:'This asks only which literal limitation is printed on the identified slide, with the attribution condition already supplied.',
 15:'This directly matches revolute and prismatic coordinate types to torque and force units.',
 16:'This directly recalls the minimal-coordinate count and qdot definition printed on the slide.',
 29:'This directly reads the marked COM-radius dimension and its accompanying sentence.',
 30:'With the z rotation axis explicitly given, this selects the corresponding two diagonal tensor entries.',
 53:'This asks for the basic derivation workflow, not an actual multi-stage symbolic derivation.'
}.items():flag(i,'difficulty','Change medium to easy. '+why)
flag(48,'difficulty','Change hard to medium. Compute two scalar inertia coefficients and use one conserved-angular-momentum ratio. The distinction from energy conservation is useful, but the arithmetic and reasoning are short.')
flag(49,'difficulty','Change hard to medium. The two components of V are supplied. One two-term dot product and the derivative of the single variable mass-matrix entry establish the identity.')
for i in [37,47]:flag(i,'assumptions','Define the author-introduced shorthand A(d2)=m1 l1²+Izz1+Izz2+m2 d2² in this question’s stem or assumptions. The cited slides display the expanded coefficient, not the symbol A, and a standalone shuffled item must not rely on Q032/Q038 or on its answer-only formula section to define that symbol.')
flag(25,'explanation','The last solution step calls mgl cos(theta)−kt theta the "physical net torque" although the shared model allows a nonzero externally applied tau. Call this the combined gravity-and-spring torque, or include +tau in the total net torque. If restricting to the source unforced equation, explicitly state tau=0. The gravity-expression key itself is correct.')
flag(34,'explanation','Refine the o2 explanation and copied misconception. The full angle derivative of U2 is m2*g*d2*cos(theta1), not the offered m2*g*cos(theta1). State that o2 incorrectly replaces sine by cosine (and is not the full angle derivative), rather than describing it as simply differentiating U2 with respect to the angle.')
flag(40,'sourceSupport','Mark the p446 lower standalone mass-matrix evidence as conflict and add version-bound question-level conflictResolution. Its underscore-like glyph is genuinely visible and differs from the clear +m2*d2² in K on p443, the upper scalar torque and upper full matrix on p446. The correct coefficient follows from the kinetic-energy Hessian. The prose handles this honestly, but the current premise citation and missing structured resolution do not preserve the distinction in the machine-readable provenance. Do not mark the whole page or PDF globally resolved; unaffected upper equations remain valid evidence.')
now=datetime.datetime.now(datetime.timezone.utc).isoformat();reviewer=blind['reviewerId'];reviews=[]
for qid,q in qs.items():
 a=answers[qid];checks={k:True for k in CHECK_KEYS}
 for f in flags.get(qid,[]):checks[f['check']]=False
 assert reviewer not in {q['authorId'],*q.get('revisionAuthors',[])}
 refs=q['citations']
 reviews.append({'id':f'REV-{qid}-v1-interface-independent','questionId':qid,'questionVersion':q['version'],'questionSha256':question_hash(q),'reviewerId':reviewer,'decision':'flagged' if qid in flags else 'verified','reviewedAt':now,'sourceVersions':{c['sourceId']:c['sourceSha256'] for c in refs},'reviewedSlideIds':a['reviewedSlideIds'],'sourceInspectionEvidence':[{'physicalPage':c['physicalPage'],'inspectorIds':[reviewer],'previewSha256':hashlib.sha256((R/f"sources/previews/lectures/page-{c['physicalPage']:04d}.webp").read_bytes()).hexdigest()} for c in refs],'independentAnswerOptionIds':a['independentAnswerOptionIds'],'solvedBeforeAnswerSeen':True,'checks':checks,'reasoning':a['reasoning']+' After the source-first answer freeze, I inspected every keyed explanation, solution step, unique formula record, source citation and classification. All intended answer sets agree. Independent symbolic Euler–Lagrange derivations, Cartesian force/spin virtual-work calculations, finite-difference energy/potential checks, angular-momentum tests and all numerical examples passed 2,218 cases. No author calculation code was imported. Recall-only items need no separate arithmetic. Figure fidelity covers actual downward/upward coordinate diagrams, COM radii, gravity arrows, derivative vectors and the lower matrix glyph. Source-attributed statements are not promoted to universal facts. Deliberate concept/application/special-case distinctions are retained; no excessive duplication was found. Distinct quality failures are listed separately.','findings':[f['finding'] for f in flags.get(qid,[])],'reviewType':'independent_blind_initial_review','priorReviewerExposure':False,'priorAuthorExposure':False,'blindAnswersPath':str(blindpath.relative_to(R)),'blindAnswersSha256':hashlib.sha256(blindpath.read_bytes()).hexdigest(),'computationsPath':'audits/W03-L14-independent-computations.json'})
p=R/'data/reviews/W03-L14-v1-independent.json';assert not p.exists();p.write_text(json.dumps(reviews,ensure_ascii=False,indent=2)+'\n')
gaps=[{'physicalPage':432,'kind':'work-energy interpretation','gap':'The explicit relation between net work and change in kinetic energy, including work removed when stopping, is not directly tested. Q004 tests speed-squared scaling and Q005 energy addition. Add a concise work-to-accelerate/decelerate item, identifying net work and distinguishing work on the body from energy delivered by it.','status':'new draft question required'},{'physicalPage':431,'kind':'model-based control/AI application','gap':'The source explicitly connects Lagrangian energy models to model-based control and AI-driven dynamics learning. Q002 tests analytical versus real-time emphasis, but none of the questions directly tests this application point. Add a bounded source-based application item, without claiming an energy representation alone guarantees learning quality or physical constraint enforcement.','status':'new draft question required'}]
summary={'reviewedAt':now,'reviewed':53,'verified':53-len(flags),'flagged':len(flags),'answerAgreement':53,'answerCorrectionsRequired':0,'independentBlindReview':True,'sourcePagesInspected':list(range(428,450)),'computationGroupsPassed':len(comp['groups']),'computationCasesPassed':comp['caseCount'],'reviewPath':str(p.relative_to(R)),'blindAnswersPath':str(blindpath.relative_to(R)),'reviewedBatchSha256':hashlib.sha256(batchpath.read_bytes()).hexdigest(),'actionableFlags':flags,'flagCountsByCheck':dict(collections.Counter(f['check'] for fs in flags.values() for f in fs)),'approvedCurrentHashes':{r['questionId']:r['questionSha256'] for r in reviews if r['decision']=='verified'},'allReviewedCurrentHashes':{r['questionId']:r['questionSha256'] for r in reviews},'coverageGaps':gaps,'sourceAndScopeNotes':['All 22 actual page images and full extracted text were inspected before keys and the author sourceIssues. The assigned answer-hidden packet hash matches.','p434 limitation and Rayleigh terminology are retained only as explicit source attribution. The broad limitation is not validated as a universal impossibility theorem.','p440 is interpreted as a tau=0 specialization, and p441 degree notation is reconciled with radian spring coordinates. Their explicitly bounded interpretations are not global corrections of the PDF.','The p446 lower glyph conflict is local; the clear upper matrix and scalar torque equations remain usable for other questions.','Q036 has cross-option wording, while Q037/Q047 introduce an undefined shortcut A. These are item independence/readability problems, not wrong intended keys.','No authored question, inspection record, canonical bank, source ledger or Git state was modified.'],'nonblockingStyleNotes':['Current formula records generally define symbols and units well. Minor prose/number joins should be fixed when a question is already versioned, without silently changing accepted hashes.','The broad p447 phrase that two scalar energies encode all dynamics needs the same conservative-load/model scope already used by the authored formula assumptions; arbitrary nonconservative loads still require explicit generalized efforts.']}
(R/'audits/W03-L14-independent-summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n');(R/'audits/W03-L14-coverage-gaps.json').write_text(json.dumps(gaps,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({k:summary[k] for k in ['reviewed','verified','flagged','answerAgreement','computationCasesPassed','flagCountsByCheck']},indent=2))
